-- State transitions declared for Mailing: an undeclared move is refused.
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION mailing.mailings_state_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."state" IS DISTINCT FROM OLD."state" AND NOT (
           (COALESCE(OLD."state"::text, ''), COALESCE(NEW."state"::text, '')) IN (('done', 'draft'), ('done', 'in_queue'), ('draft', 'in_queue'), ('in_queue', 'done'), ('in_queue', 'draft'), ('in_queue', 'sending'), ('sending', 'done'), ('sending', 'draft'), ('sending', 'in_queue'))
       ) THEN
        RAISE EXCEPTION 'state_transition_not_declared: mailings.state % -> %', OLD."state", NEW."state"
            USING ERRCODE = 'check_violation', COLUMN = 'state', CONSTRAINT = 'tg_mailings__state_transition_not_declared';
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS mailings_state_transition_check ON mailing.mailings;
CREATE TRIGGER mailings_state_transition_check
    BEFORE UPDATE OF "state" ON mailing.mailings
    FOR EACH ROW EXECUTE FUNCTION mailing.mailings_state_transition_check();
